return $input.all().flatMap(({json:{post_id,findings}}, itemIndex)=>{
if (!Number.isSafeInteger(post_id)||post_id<1||!Array.isArray(findings)||findings.length<1||findings.length>30) throw Error('Parecer de entrada inválido.');
const seen=new Set();
return findings.flatMap(({claim}, index)=>{
 if(typeof claim!=='string'||!claim.trim()||claim.length>1000)throw Error('Afirmação inválida.');
 const query=claim.trim().replace(/\s+/g,' ');
 const key=query.toLocaleLowerCase('pt-BR');
 if(seen.has(key))return [];
 seen.add(key);
 return [{json:{post_id,claim_index:index,claim:query},pairedItem:{item:itemIndex}}];
});
});

const input=$('Preparar consultas').item.json;
const status=$json.statusCode;
const body=$json.body??$json.data;
const ok=status===200&&body&&typeof body==='object'&&!Array.isArray(body)&&!body.error&&(body.claims===undefined||Array.isArray(body.claims));
const candidates=ok?(body.claims??[]).slice(0,5).flatMap(c=>(Array.isArray(c?.claimReview)?c.claimReview:[]).slice(0,5)
 .filter(r=>typeof r?.url==='string'&&/^https?:\/\//i.test(r.url))
 .map(r=>({text:c.text??'',publisher:r.publisher?.name??'',rating:r.textualRating??'',reviewDate:r.reviewDate??null,url:r.url}))):[];
return {json:{...input,status:ok?(candidates.length?'candidatos':'sem_resultados'):'consulta_indisponivel',http_status:status??null,candidates,verdict:null,modelCalls:0}};
